/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void rxt_error (Rxt_Error_Code code)
{  
	UInt8 ptr = rxt_err.count % RXT_ERR_BUFF_SIZE ;	
	rxt_err.code [ptr] = code ;	
	rxt_err.count++ ;
	
	nvfs_wr (nvfs_rxt_err, &rxt_err) ; 
}

